import { Controller, Get, Post, Put, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';

// 가정: 계좌번호 암호화 키 (AES, 32바이트). 키 관리 방식이 정해지지 않아 상수로 둔다.
const ACCOUNT_KEY = 'partner-account-key-32bytes-0001';
// 가정: 같은 키·같은 방식이면 같은 암호문이 나와야 중복 검사가 가능하므로 AES 결정적 암호화를 쓴다.
const ENC_SQL = "encode(encrypt(convert_to(CAST(:accountNo AS text), 'UTF8'), convert_to(CAST(:key AS text), 'UTF8'), 'aes'), 'base64')";

function invalid(): ApiError {
  return new ApiError(422, 'PARTNER_ACCOUNT_INPUT_INVALID', '필수 값이 없거나 형식이 올바르지 않습니다.');
}

function textOf(v: unknown, max: number): string {
  if (typeof v !== 'string' || v.trim() === '' || v.trim().length > max) {
    throw invalid();
  }
  return v.trim();
}

function idOf(v: unknown): string {
  const s = typeof v === 'number' ? String(v) : v;
  if (typeof s !== 'string' || !/^\d+$/.test(s)) {
    throw invalid();
  }
  return s;
}

function useYnOf(v: unknown): string | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  if (v !== '사용' && v !== '미사용') {
    throw invalid();
  }
  return v;
}

@Controller('api/v1')
export class FnSfr00205Controller {
  @Post('/partner-accounts')
  @HttpCode(200)
  async createPartnerAccount(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const partnerId = idOf(data['partnerId']);
    const bankName = textOf(data['bankName'], 100);
    const accountNo = textOf(data['accountNo'], 100);
    const accountHolder = textOf(data['accountHolder'], 100);
    const useYn = useYnOf(data['useYn']);
    return transaction(async (db) => {
      const partners = await db.query(
        'SELECT partner_id FROM partner WHERE partner_id = CAST(:partnerId AS bigint)',
        { partnerId },
      );
      if (partners.length === 0) {
        throw new ApiError(404, 'PARTNER_NOT_FOUND', '거래처를 찾을 수 없습니다.');
      }
      const encRows = await db.query('SELECT ' + ENC_SQL + ' AS enc', { accountNo, key: ACCOUNT_KEY });
      const enc = encRows[0]['enc'];
      const dup = await db.query(
        'SELECT partner_account_id FROM partner_account WHERE partner_id = CAST(:partnerId AS bigint) AND bank_name = :bankName AND account_no_enc = :enc',
        { partnerId, bankName, enc },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'PARTNER_ACCOUNT_DUPLICATED', '동일 거래처에 같은 은행·계좌번호가 이미 등록되어 있습니다.');
      }
      const rows = await db.query(
        'INSERT INTO partner_account (partner_id, bank_name, account_no_enc, account_holder, use_yn, created_at, updated_at) ' +
          "VALUES (CAST(:partnerId AS bigint), :bankName, :enc, :accountHolder, COALESCE(CAST(:useYn AS varchar), '사용'), now(), now()) " +
          'RETURNING partner_account_id AS "partnerAccountId"',
        { partnerId, bankName, enc, accountHolder, useYn },
      );
      return rows[0];
    });
  }

  @Put('/partner-accounts/:partnerAccountId')
  async updatePartnerAccount(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = req.params['partnerAccountId'];
    const data = checks.inputOf(req.body);
    const bankName = textOf(data['bankName'], 100);
    const accountNo = textOf(data['accountNo'], 100);
    const accountHolder = textOf(data['accountHolder'], 100);
    const useYn = useYnOf(data['useYn']);
    return transaction(async (db) => {
      if (!/^\d+$/.test(id)) {
        throw new ApiError(404, 'PARTNER_ACCOUNT_NOT_FOUND', '계좌를 찾을 수 없습니다.');
      }
      const found = await db.query(
        'SELECT partner_id AS "partnerId" FROM partner_account WHERE partner_account_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PARTNER_ACCOUNT_NOT_FOUND', '계좌를 찾을 수 없습니다.');
      }
      const partnerId = String(found[0]['partnerId']);
      const encRows = await db.query('SELECT ' + ENC_SQL + ' AS enc', { accountNo, key: ACCOUNT_KEY });
      const enc = encRows[0]['enc'];
      const dup = await db.query(
        'SELECT partner_account_id FROM partner_account WHERE partner_id = CAST(:partnerId AS bigint) AND bank_name = :bankName AND account_no_enc = :enc AND partner_account_id <> CAST(:id AS bigint)',
        { partnerId, bankName, enc, id },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'PARTNER_ACCOUNT_DUPLICATED', '동일 거래처에 같은 은행·계좌번호가 이미 등록되어 있습니다.');
      }
      const rows = await db.query(
        'UPDATE partner_account SET bank_name = :bankName, account_no_enc = :enc, account_holder = :accountHolder, ' +
          'use_yn = COALESCE(CAST(:useYn AS varchar), use_yn), updated_at = now() ' +
          'WHERE partner_account_id = CAST(:id AS bigint) RETURNING partner_account_id AS "partnerAccountId"',
        { bankName, enc, accountHolder, useYn, id },
      );
      return rows[0];
    });
  }

  @Delete('/partner-accounts/:partnerAccountId')
  async deletePartnerAccount(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = req.params['partnerAccountId'];
    return transaction(async (db) => {
      if (!/^\d+$/.test(id)) {
        throw new ApiError(404, 'PARTNER_ACCOUNT_NOT_FOUND', '계좌를 찾을 수 없습니다.');
      }
      const count = await db.execute(
        'DELETE FROM partner_account WHERE partner_account_id = CAST(:id AS bigint)',
        { id },
      );
      if (count === 0) {
        throw new ApiError(404, 'PARTNER_ACCOUNT_NOT_FOUND', '계좌를 찾을 수 없습니다.');
      }
      return {};
    });
  }

  @Get('/partner-accounts')
  async listPartnerAccounts(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const partnerIdRaw = query['partnerId'];
    if (typeof partnerIdRaw !== 'string' || !/^\d+$/.test(partnerIdRaw)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '거래처 ID가 필요합니다.');
    }
    const pageRaw = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    const sizeRaw = query['size'] === undefined || query['size'] === '' ? 20 : Number(query['size']);
    if (!Number.isInteger(pageRaw) || pageRaw < 0 || !Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 크기가 올바르지 않습니다.');
    }
    const page = pageRaw;
    const size = Math.min(sizeRaw, 200);
    return transaction(async (db) => {
      const totalRows = await db.query(
        'SELECT COUNT(*) AS total FROM partner_account WHERE partner_id = CAST(:partnerId AS bigint)',
        { partnerId: partnerIdRaw },
      );
      const items = await db.query(
        'SELECT partner_account_id AS "partnerAccountId", bank_name AS "bankName", account_holder AS "accountHolder", use_yn AS "useYn" ' +
          'FROM partner_account WHERE partner_id = CAST(:partnerId AS bigint) ' +
          'ORDER BY partner_account_id LIMIT :size OFFSET :offset',
        { partnerId: partnerIdRaw, size, offset: page * size },
      );
      return { items, page, size, total: Number(totalRows[0]['total']) };
    });
  }
}

