import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  Select,
  Filters,
  Tiles,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const USE_OPTIONS: [string, string][] = [
  ['사용', '사용'],
  ['미사용', '미사용'],
];

const SIZE = 20;

export default function FnSfr00205Page({ role, notify }: PageProps) {
  const [partnerId, setPartnerId] = useState<number | string>('');
  const [applied, setApplied] = useState<number | string>('');
  const [pageNo, setPageNo] = useState(0);
  const [mode, setMode] = useState<'' | 'create' | 'edit' | 'delete'>('');
  const [target, setTarget] = useState<Row | null>(null);
  const [bankName, setBankName] = useState('');
  const [accountNo, setAccountNo] = useState('');
  const [accountHolder, setAccountHolder] = useState('');
  const [useYn, setUseYn] = useState('사용');

  const list = useData<Page>(async () => {
    if (applied === '') {
      return { items: [], page: 0, size: SIZE, total: 0 };
    }
    return call<Page>('GET', '/partner-accounts', role, undefined, {
      partnerId: applied,
      page: pageNo,
      size: SIZE,
    });
  }, [applied, pageNo]);

  const page = list.data;
  const rows = page ? page.items : [];
  const total = page ? page.total : 0;

  function close() {
    setMode('');
    setTarget(null);
  }

  function openCreate() {
    setBankName('');
    setAccountNo('');
    setAccountHolder('');
    setUseYn('사용');
    setMode('create');
  }

  function openEdit(row: Row) {
    setTarget(row);
    setBankName(String(row['bankName'] ?? ''));
    setAccountNo('');
    setAccountHolder(String(row['accountHolder'] ?? ''));
    setUseYn(String(row['useYn'] ?? '사용'));
    setMode('edit');
  }

  function openDelete(row: Row) {
    setTarget(row);
    setMode('delete');
  }

  function search() {
    setPageNo(0);
    setApplied(partnerId);
  }

  function reset() {
    setPartnerId('');
    setApplied('');
    setPageNo(0);
  }

  function checkInputs() {
    if (bankName.trim() === '' || accountNo.trim() === '' || accountHolder.trim() === '') {
      throw new Error('은행명, 계좌번호, 예금주를 모두 입력해 주세요.');
    }
  }

  async function submitCreate() {
    if (applied === '') {
      throw new Error('거래처를 먼저 선택하고 조회해 주세요.');
    }
    checkInputs();
    await call('POST', '/partner-accounts', role, {
      partnerId: applied,
      bankName: bankName.trim(),
      accountNo: accountNo.trim(),
      accountHolder: accountHolder.trim(),
      useYn,
    });
    notify('계좌를 등록했습니다.');
    close();
    list.reload();
  }

  async function submitEdit() {
    if (!target) {
      return;
    }
    checkInputs();
    await call('PUT', '/partner-accounts/' + String(target['partnerAccountId']), role, {
      bankName: bankName.trim(),
      accountNo: accountNo.trim(),
      accountHolder: accountHolder.trim(),
      useYn,
    });
    notify('계좌를 수정했습니다.');
    close();
    list.reload();
  }

  async function submitDelete() {
    if (!target) {
      return;
    }
    await call('DELETE', '/partner-accounts/' + String(target['partnerAccountId']), role);
    notify('계좌를 삭제했습니다.');
    close();
    list.reload();
  }

  const columns = [
    { key: 'partnerAccountId', label: '거래처 계좌 ID' },
    { key: 'bankName', label: '은행명' },
    { key: 'accountHolder', label: '예금주' },
    { key: 'useYn', label: '사용 여부', render: (r: Row) => <Badge value={r['useYn']} /> },
    {
      key: 'actions',
      label: '처리',
      render: (r: Row) => (
        <span>
          <button type="button" onClick={(e) => { e.stopPropagation(); openEdit(r); }}>수정</button>
          <button type="button" onClick={(e) => { e.stopPropagation(); openDelete(r); }}>삭제</button>
        </span>
      ),
    },
  ];

  const formFields = (
    <>
      <Field label="은행명" required>
        <TextInput value={bankName} onChange={setBankName} />
      </Field>
      <Field label="계좌번호(암호화 저장)" required hint="저장 후에는 보이지 않으므로 수정 시 다시 입력합니다.">
        <TextInput value={accountNo} onChange={setAccountNo} />
      </Field>
      <Field label="예금주" required>
        <TextInput value={accountHolder} onChange={setAccountHolder} />
      </Field>
      <Field label="사용 여부">
        <Select value={useYn} onChange={setUseYn} options={USE_OPTIONS} placeholder="선택" />
      </Field>
    </>
  );

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>조회 거래처</h2>
        <Tiles items={[['계좌 수', total]]} />
        {applied !== '' && (
          <p>
            <RefName table="partner" role={role} value={applied} />
          </p>
        )}
      </section>
      <section className="box span-8">
        <h2>거래처 계좌</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="거래처 ID" required>
            <LookupSelectPartner role={role} value={partnerId} onChange={setPartnerId} />
          </Field>
        </Filters>
        <Band total={total}>
          <button type="button" disabled={applied === ''} onClick={openCreate}>계좌 등록</button>
        </Band>
        {list.error !== '' && <ErrorText text={list.error} />}
        <DataTable columns={columns} rows={rows} empty="거래처를 선택해 조회해 주세요." />
        <Pager page={pageNo} size={SIZE} total={total} onPage={setPageNo} />
      </section>
      {mode === 'create' && (
        <Drawer title="거래처 계좌 등록" onClose={close}>
          <Form onSubmit={submitCreate} submit="등록">
            {formFields}
          </Form>
        </Drawer>
      )}
      {mode === 'edit' && target && (
        <Drawer title="거래처 계좌 수정" onClose={close}>
          <Form onSubmit={submitEdit} submit="수정">
            {formFields}
          </Form>
        </Drawer>
      )}
      {mode === 'delete' && target && (
        <Drawer title="거래처 계좌 삭제" onClose={close}>
          <Form
            onSubmit={submitDelete}
            submit="삭제"
            danger
            note={'은행명 ' + String(target['bankName'] ?? '') + ' 계좌를 삭제합니다.'}
          />
        </Drawer>
      )}
    </div>
  );
}

function LookupSelectPartner({
  role,
  value,
  onChange,
}: {
  role: string;
  value: number | string;
  onChange: (v: number | string) => void;
}) {
  return <LookupSelect table="partner" role={role} value={value} onChange={onChange} placeholder="거래처 선택" />;
}
